#include <iostream>
#include <algorithm>
using namespace std;



int main(){

  int numCities, numPaths, cityA, cityB, travelCost, travelTime, numQueries, queryCityA, queryCityB, queryType;

  int time[100][100], cost[100][100];



  for(;;){

    cin >> numCities >> numPaths;

    if(!numCities && !numPaths) break;



    fill(&time[0][0], &time[0][0]+100*100, 1000000);

    fill(&cost[0][0], &cost[0][0]+100*100, 1000000);



    for(int i=0;i<numPaths;i++){

      time[i][i] = 0;

      cost[i][i] = 0;

    }



    for(int i=0;i<numCities;i++){

      cin >> cityA >> cityB >> travelCost >> travelTime;

      time[cityA-1][cityB-1] = travelTime;

      time[cityB-1][cityA-1] = travelTime;

      cost[cityA-1][cityB-1] = travelCost;

      cost[cityB-1][cityA-1] = travelCost;

    }



    for(int k=0;k<numPaths;k++){

      for(int i=0;i<numPaths;i++){

	for(int j=0;j<numPaths;j++){

	  time[i][j] = min(time[i][j],time[i][k] + time[k][j]);

	  cost[i][j] = min(cost[i][j],cost[i][k] + cost[k][j]);

	}

      }

    }



    cin >> numQueries;

    for(int i=0;i<numQueries;i++){

      cin >> queryCityA >> queryCityB >> queryType;

      if(queryType)

	cout << time[queryCityA-1][queryCityB-1] << endl;

      else

	cout << cost[queryCityA-1][queryCityB-1] << endl;

    }

  }

}

